<?php require __DIR__.'/_guard.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();$pid=(int)$_POST['product_id'];$qty=max(1,(int)$_POST['qty']);db()->beginTransaction();try{$q=db()->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$p=$q->fetch();if(!$p||$p['stock']<$qty)throw new RuntimeException('Not enough stock');$total=(float)$p['price']*$qty;$q=db()->prepare("INSERT INTO orders(customer_name,email,phone,address,city,subtotal,grand_total,payment_method,payment_status,order_status,source) VALUES(?,?,?,?,?,?,?,?, 'paid','delivered','pos')");$q->execute([$_POST['customer']?:'Walk-in','',$_POST['phone']??'','Counter sale','Faisalabad',$total,$total,$_POST['method']]);$oid=(int)db()->lastInsertId();db()->prepare('INSERT INTO order_items(order_id,product_id,product_name,sku,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?,?)')->execute([$oid,$pid,$p['name'],$p['sku'],$p['price'],$qty,$total]);db()->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$pid]);db()->prepare("INSERT INTO stock_movements(product_id,quantity_change,reason,reference_id,user_id) VALUES(?,?,'pos_sale',?,?)")->execute([$pid,-$qty,$oid,Auth::user()['id']]);db()->commit();$msg="POS sale saved. Invoice #$oid";}catch(Throwable $e){db()->rollBack();$msg=$e->getMessage();}}$products=db()->query("SELECT id,name,sku,price,stock FROM products WHERE status='active' AND stock>0 ORDER BY name")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main class="narrow"><a href="/admin/">← Dashboard</a><h1>Point of Sale</h1><p><?=e($msg)?></p><form method="post"><?=Security::field()?><label>Product<select name="product_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> · <?=money($p['price'])?> · Stock <?=$p['stock']?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="qty" value="1" min="1"></label><label>Customer<input name="customer" value="Walk-in"></label><label>Phone<input name="phone"></label><label>Payment<select name="method"><option value="cash">Cash</option><option value="bank">Bank</option></select></label><button>Complete sale</button></form></main></body></html>